PROSE=re.compile(r'(?i)\b(your|paste|here|the\s|account|dashboard|found|goes|replace|example|todo|xxx|paste_|<|placeholder|settings|copy)\b')
def classify(k,v):
    if not v: return "EMPTY"
    # prose = contains multiple spaces AND english filler words
    if v.count(" ")>=2 and PROSE.search(v): return "PROSE/DESCRIPTION — NOT A CREDENTIAL"
    if v.count(" ")>=2: return "SUSPICIOUS (contains spaces)"
    if v.startswith("eyJ"):
        try:
            p=v.split(".")[1]; p+="="*(-len(p)%4)
            c=json.loads(base64.urlsafe_b64decode(p))
            iss=c.get("iss"); ref=c.get("ref")
            if iss=="supabase-demo" or not ref: return f"DEMO/INVALID JWT (iss={iss}, ref empty)"
            return f"JWT role={c.get('role')} ref={ref}"
        except Exception: return "JWT unparseable"
    return "looks like a value"

print(f"{'VARIABLE':36} VERDICT")
bad=[]
for k,v in E.items():
    c=classify(k,v)
    if "PROSE" in c or "DEMO" in c or c=="EMPTY" or "SUSPICIOUS" in c: bad.append((k,c))
    print(f"{k:36} {c}")
print("\n=== UNUSABLE ("+str(len(bad))+") ===")
for k,c in bad: print(f"  {k:36} {c}")
