import re,json,base64,subprocess
raw=open("expo/.env",errors="replace").read()
E={}
for m in re.finditer(r'(?m)^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=(.*)$',raw):
    E[m.group(1)]=m.group(2).strip().strip('"').strip("'")

def curl(url,hdrs=None,method="GET",data=None):
    c=["curl","-s","-m","20","-o","/tmp/o","-w","%{http_code}","-X",method,url]
    for k,v in (hdrs or {}).items(): c+=["-H",f"{k}: {v}"]
    if data: c+=["-d",data]
    try: code=subprocess.run(c,capture_output=True,text=True,timeout=25).stdout.strip()
    except Exception: return "TIMEOUT",""
    try: body=open("/tmp/o",errors="replace").read()
    except Exception: body=""
    return code,body

R=[]
def rec(n,s,d=""): R.append((n,s,"VALID" if s in("200","201","204") else "INVALID",d))

c,b=curl("https://api.supabase.com/v1/projects",{"Authorization":"Bearer "+E.get("SUPABASE_ACCESS_TOKEN","")})
d=""
if c=="200":
    try: d=f"{len(json.loads(b))} project(s) visible"
    except Exception: d="ok"
else: d=b[:60].replace("\n"," ")
rec("SUPABASE_ACCESS_TOKEN (mgmt)",c,d)

url=E.get("EXPO_PUBLIC_SUPABASE_URL","")
for key in ["SUPABASE_SERVICE_ROLE_KEY","EXPO_PUBLIC_SUPABASE_ANON_KEY"]:
    k=E.get(key,"")
    c,b=curl(f"{url}/rest/v1/investor_profiles?select=id&limit=1",{"apikey":k,"Authorization":"Bearer "+k})
    rec(key,c,"live project accepts it" if c=="200" else b[:55].replace("\n"," "))

for key in ["GITHUB_TOKEN","RORK_PUBLIC_GITHUB_TOKEN"]:
    c,b=curl("https://api.github.com/user",{"Authorization":"Bearer "+E.get(key,""),"User-Agent":"ivx-audit"})
    rec(key,c,"authenticated" if c=="200" else "rejected by GitHub")

sid,tok=E.get("IVX_TWILIO_ACCOUNT_SID",""),E.get("IVX_TWILIO_AUTH_TOKEN","")
ba=base64.b64encode(f"{sid}:{tok}".encode()).decode()
c,b=curl(f"https://api.twilio.com/2010-04-01/Accounts/{sid}.json",{"Authorization":"Basic "+ba})
d=""
if c=="200":
    try: d="account status="+json.loads(b).get("status","?")
    except Exception: d="ok"
else:
    try: d=json.loads(b).get("message","")[:55]
    except Exception: d=b[:55].replace("\n"," ")
rec("IVX_TWILIO_ACCOUNT_SID + AUTH_TOKEN",c,d)

for key in ["AI_GATEWAY_API_KEY","IVX_AI_GATEWAY_KEY","RORK_PUBLIC_IVX_AI_KEY"]:
    c,b=curl("https://ai-gateway.vercel.sh/v1/models",{"Authorization":"Bearer "+E.get(key,"")})
    rec(key,c,"gateway accepts" if c=="200" else b[:55].replace("\n"," "))

print(f"{'CREDENTIAL':40} {'HTTP':6} {'VERDICT':8} DETAIL")
for n,s,v,d in R: print(f"{n:40} {s:6} {v:8} {d}")
print("\nVALID="+str(sum(1 for x in R if x[2]=='VALID'))+"  INVALID="+str(sum(1 for x in R if x[2]=='INVALID')))
